# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">AVRUPA\'DAKİ GELİŞMELER VE OSMANLI DEVLETİ\'NE ETKİLERİ (SB.7.3.2)</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">1. Coğrafi Keşifler (XV-XVI. yy)</text>\n  <text x="34" y="98" font-size="11" fill="#334155">• Yeni ticaret yolları ve kıtalar</text>\n  <text x="34" y="120" font-size="11" fill="#334155">• İpek ve Baharat Yolu önem</text>\n  <text x="34" y="138" font-size="11" fill="#334155">  kaybetti (Atlas Okyanusu öne çıktı)</text>\n  <text x="34" y="162" font-size="11" fill="#334155">• Osmanlı gümrük gelirleri azaldı,</text>\n  <text x="34" y="180" font-size="11" fill="#334155">  altın-gümüşle enflasyon arttı</text>\n  <text x="125" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">Ekonomik Dengenin Değişmesi</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. Rönesans, Reform ve Aydınlanma</text>\n  <text x="259" y="98" font-size="11" fill="#334155">• Rönesans (İtalya): Bilim, sanat,</text>\n  <text x="259" y="118" font-size="11" fill="#334155">  edebiyatta yeniden doğuş</text>\n  <text x="259" y="140" font-size="11" fill="#334155">• Reform (Almanya): Skolastik</text>\n  <text x="259" y="160" font-size="11" fill="#334155">  düşünce yıkıldı, özgür bilim doğdu</text>\n  <text x="259" y="182" font-size="11" fill="#334155">• Aydınlanma Çağı: Akıl ve deney</text>\n  <text x="350" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">Bilimsel ve Teknolojik Üstünlük</text>\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">3. Sanayi İnkılabı ve Fransız İhtilali</text>\n  <text x="484" y="98" font-size="11" fill="#334155">• Sanayi İnkılabı (İngiltere):</text>\n  <text x="484" y="118" font-size="11" fill="#334155">  Buhar gücü ve seri üretim; Osmanlı</text>\n  <text x="484" y="138" font-size="11" fill="#334155">  lonca tezgâhları rekabet edemedi</text>\n  <text x="484" y="162" font-size="11" fill="#334155">• Fransız İhtilali (1789): Eşitlik,</text>\n  <text x="484" y="182" font-size="11" fill="#334155">  hürriyet ve milliyetçilik akımı</text>\n  <text x="575" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#92400e">Siyasi ve İktisadi Islahat İhtiyacı</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">XVIII. YÜZYIL YENİLİKLERİ: LALE DEVRİ VE NİZAM-I CEDİT</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="182" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#be185d">Lale Devri Yenilikleri (1718 - 1730)</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• İlk Türk Matbaası (1727): İbrahim Müteferrika</text>\n  <text x="40" y="118" font-size="11" fill="#334155">  ve Said Efendi (İlk eser: Vankulu Lügatı - 1729)</text>\n  <text x="40" y="140" font-size="11" fill="#334155">• Avrupa\'ya ilk geçici elçilikler (Paris - Yirmisekiz</text>\n  <text x="40" y="158" font-size="11" fill="#334155">  Çelebi Mehmet Efendi)</text>\n  <text x="40" y="180" font-size="11" fill="#334155">• Tulumbacılar Ocağı (İlk itfaiye) ve çiçek aşısı</text>\n  <text x="40" y="200" font-size="11" fill="#334155">• Yalova\'da kâğıt, İstanbul\'da kumaş ve çini imalathanesi</text>\n  <text x="182" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">Padişah: III. Ahmet | Sadrazam: Nevşehirli Damat İbrahim</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="517" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Askerî Islahatlar ve III. Selim Dönemi</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Hendesehane (I. Mahmut) ve Mühendishane-i</text>\n  <text x="375" y="118" font-size="11" fill="#334155">  Bahr-i Hümâyun (Deniz Mühendishanesi - 1773)</text>\n  <text x="375" y="140" font-size="11" fill="#334155">• III. Selim: Nizam-ı Cedit (Yeni Düzen) ordusu</text>\n  <text x="375" y="160" font-size="11" fill="#334155">• İrad-ı Cedit hazinesi ve Mühendishane-i Berr-i Hümâyun</text>\n  <text x="375" y="182" font-size="11" fill="#334155">• Avrupa başkentlerinde ilk kalıcı (daimî) elçilikler</text>\n  <text x="375" y="200" font-size="11" fill="#334155">  (İlk kalıcı elçilik: Londra - Yusuf Agâh Efendi)</text>\n  <text x="517" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Planlı ve Radikal Devlet Yenileşmesi</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">XIX. YÜZYIL ISLAHATLARI: II. MAHMUT, TANZİMAT VE ULAŞIM-İLETİŞİM</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="182" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">II. Mahmut ve Tanzimat Dönemi Kurumları</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Vaka-i Hayriye (1826): Yeniçeri Ocağı kaldırıldı,</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  Asâkir-i Mansûre-i Muhammediye ordusu kuruldu</text>\n  <text x="40" y="138" font-size="11" fill="#334155">• Takvim-i Vekayi (1831): İlk resmî gazete</text>\n  <text x="40" y="158" font-size="11" fill="#334155">• Divan-ı Hümâyun yerine Nazırlıklar (Bakanlıklar)</text>\n  <text x="40" y="178" font-size="11" fill="#334155">• Tanzimat (1839) ve Islahat (1856) Fermanları</text>\n  <text x="40" y="198" font-size="11" fill="#334155">• Kanun-i Esasi ve I. Meşrutiyet (1876)</text>\n  <text x="182" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Hukuk Üstünlüğü ve Modern Devlet Teşkilatı</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="517" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">Ulaşım, Haberleşme, Ekonomi ve Eğitim</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Posta Nezareti (1840) ve Telgraf Hattı (1855)</text>\n  <text x="375" y="120" font-size="11" fill="#334155">• Şirket-i Hayriye (1851 - Boğaz vapurları)</text>\n  <text x="375" y="142" font-size="11" fill="#334155">• İlk Demiryolu: İzmir-Aydın (Anadolu\'da, 1856)</text>\n  <text x="375" y="164" font-size="11" fill="#334155">• Memleket Sandıkları (1863) → Ziraat Bankası (1888)</text>\n  <text x="375" y="186" font-size="11" fill="#334155">• Rüştiyeler, Mekteb-i Tıbbiye, Harbiye, Mülkiye</text>\n  <text x="517" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Merkezî Otorite ve Toplumsal Modernleşme</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
